"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["72468"],{83239(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.termo_consentimento.revisao_sem_texto","status":422,"titulo":"Rascunho sem texto n\xe3o pode ser marcado como revisado nem promovido"},"descricao":{"codigo":"uniplus.configuracao.termo_consentimento.revisao_sem_texto","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["A revis\xe3o institucional \xe9 a verifica\xe7\xe3o que antecede a promo\xe7\xe3o do rascunho a vers\xe3o do termo, e s\xf3 se marca um rascunho que tenha texto (UNI-REQ-0086). O pedido (`POST /api/configuracao/admin/termos-consentimento/{id}/revisar`) chegou para um termo cujo rascunho est\xe1 sem texto, vazio ou s\xf3 com espa\xe7os, e a API n\xe3o registra a revis\xe3o de um texto que n\xe3o existe.","A busca do termo vem antes: com um `{id}` que n\xe3o existe, a resposta \xe9 a de termo n\xe3o encontrado (`uniplus.configuracao.termo_consentimento.nao_encontrado`). Quando o rascunho est\xe1 sem texto e sem base legal, esta \xe9 a recusa que vem, porque o texto \xe9 conferido primeiro; resolvida a falta do texto, a falta da base legal \xe9 a seguinte (`uniplus.configuracao.termo_consentimento.revisao_sem_base_legal`). Nada \xe9 gravado.","A promo\xe7\xe3o de um rascunho sem texto n\xe3o chega a esta confer\xeancia: ela exige a revis\xe3o antes, e a revis\xe3o n\xe3o \xe9 marcada sem texto (`uniplus.configuracao.termo_consentimento.promocao_sem_revisao`)."],"comoResolver":["Escreva o texto do rascunho (`PUT /api/configuracao/admin/termos-consentimento/{id}/rascunho`, com o texto, a base legal e a forma de aceite) e pe\xe7a a revis\xe3o de novo."],"ondeAparece":["Marca\xe7\xe3o do rascunho de um termo de consentimento como revisado"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Termo consentimento"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"bac0ecb24f352b6341ba53a00922b6237dd7a678"}}')}}]);